\mathbf{b}_d(\mathbf{x})=&\Big( 1 \quad x_1 \quad x_2 \quad \cdots \quad x_1^2 \quad x_1x_2 \quad  \cdots  \quad x_1x_n \\ &  x_2^2 \quad x_2x_3 \quad  \cdots \quad x_n^2 \quad \cdots \quad x_1^d \quad \cdots \quad x_n^d \Big)^\mathrm{T}
